export class DashboardDurableObject {
  constructor(state, env) { this.state = state; this.sessions = new Set(); }
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname === "/ws") {
      if (request.headers.get("Upgrade") !== "websocket") return new Response("Expected WebSocket", { status: 426 });
      const pair = new WebSocketPair(); const client = pair[0]; const server = pair[1];
      server.accept(); this.sessions.add(server);
      server.send(JSON.stringify({ type: "init", data: await this.getData() }));
      server.addEventListener("message", async event => {
        try { const msg = JSON.parse(event.data); if (msg.type === "update") { await this.state.storage.put("dashboardData", msg.data); this.broadcast({ type: "update", data: msg.data }, server); } }
        catch (err) { server.send(JSON.stringify({ type: "error", message: String(err) })); }
      });
      server.addEventListener("close", () => this.sessions.delete(server)); server.addEventListener("error", () => this.sessions.delete(server));
      return new Response(null, { status: 101, webSocket: client });
    }
    if (url.pathname === "/api/data") {
      if (request.method === "GET") return Response.json(await this.getData());
      if (request.method === "POST") { const body=await request.json(); await this.state.storage.put("dashboardData", body); this.broadcast({type:"update",data:body}); return Response.json({ok:true}); }
    }
    return new Response("Not found", { status: 404 });
  }
  async getData() {
    const def={appVersion:"11.0.0",companyName:"บริษัท สายไฟฟ้าบางกอกเคเบิ้ล จำกัด",currentDepartmentId:"bcc2-insulation-packing",departments:[{id:"bcc2-insulation-packing",name:"ฝ่ายหุ้มฉนวนและบรรจุสาย BCC2",targetDays:"2937",monthRecords:{},manualOverrides:{},data:{}}]};
    const saved=await this.state.storage.get("dashboardData");
    if(!saved)return def;
    if(!Array.isArray(saved.departments))return {...def,departments:[{id:"default-department",name:saved.departmentName||"ฝ่ายเริ่มต้น",targetDays:saved.targetDays||"2937",monthRecords:{},data:{}}],currentDepartmentId:"default-department"};
    return {...def,...saved};
  }
  broadcast(message, exceptSocket=null) { const payload=JSON.stringify(message); for(const s of this.sessions){ if(s!==exceptSocket){ try{s.send(payload)}catch{this.sessions.delete(s)} } } }
}
const html = "<!doctype html>\n<html lang=\"th\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>BCC Safety Web Application</title>\n<style>\n@import url('https://fonts.googleapis.com/css2?family=Sarabun:wght@300;400;600;700;800&display=swap');\n*{box-sizing:border-box} body{margin:0;font-family:'TH Sarabun New','Sarabun',Tahoma,sans-serif;background:#02112c;color:#eaffff}.hidden{display:none!important}.app{min-height:100vh;background:#071a3a;border:6px solid #062b6f;padding:0 4px 14px}.login{position:fixed;inset:0;background:linear-gradient(135deg,#010716,#092b64 55%,#001638);display:grid;place-items:center;z-index:99}.login-card{width:min(460px,92vw);background:#fffffff0;color:#062047;border-radius:18px;padding:28px;border:4px solid #0b75c9;box-shadow:0 20px 60px #0008}.login-card h1{margin:0;font-size:42px;color:#064b92}.login-card p{font-size:24px}.login-card input{width:100%;font-family:inherit;font-size:28px;padding:10px 14px;margin:8px 0;border:2px solid #8fb7d9;border-radius:10px}.login-card button{width:100%;font-family:inherit;font-size:28px;font-weight:800;padding:10px;border:0;border-radius:10px;background:#064b92;color:white;cursor:pointer}.login-error{color:#b00020;font-size:22px;font-weight:800;min-height:28px}\n/* unified header/title layout */\n.unified-layout{width:100%;margin:0 auto 10px}.brand-header{height:104px;display:grid;grid-template-columns:190px 1fr 92px;align-items:center;gap:12px;background:#edf8ff;color:#031735;border:3px solid #1586df;border-radius:7px;padding:6px 10px}.bcc-logo{width:176px;height:84px;object-fit:contain;background:#053184}.bcc-logo-text{font-size:54px;font-weight:800;color:#123b8c}.brand-title{text-align:center;line-height:1.1}.company-line{font-size:34px;font-weight:800;letter-spacing:.5px}.department-line{font-size:32px;font-weight:800}.safety-circle{justify-self:end;width:78px;height:78px;border-radius:50%;background:#1087d8;border:4px solid #bce7ff;color:#fff;display:grid;place-items:center;text-align:center;font-size:12px;font-weight:800;line-height:1.15;box-shadow:0 0 0 2px #0d6fb5 inset}.title-image{height:84px;margin-top:8px;border:3px solid #1586df;border-radius:7px;overflow:hidden;background:#031a4a}.title-image-img{width:100%;height:100%;object-fit:cover;object-position:center;display:block}.title-image-fallback{height:100%;display:grid;place-items:center;font-size:34px;font-weight:800;color:white;background:linear-gradient(90deg,#020735,#063b97,#0077ff)}\n.toolbar{margin-top:10px;padding:12px 14px;background:#04142e;color:white;display:grid;grid-template-columns:1fr 1.2fr auto;gap:12px;align-items:center;border-radius:10px;border:2px solid #0b75c9;font-size:25px}.toolbar select,.toolbar input,.datebar select{font-family:inherit;font-size:24px;padding:6px 10px;border-radius:6px;border:2px solid #5eb4ff}.toolbar button,.panel button{font-family:inherit;font-size:23px;font-weight:800;border:0;border-radius:6px;padding:8px 12px;cursor:pointer;color:white}.btn-add{background:#009a72}.btn-del{background:#bd1733}.btn-save{background:#087a62}.btn-export{background:#0b58b5}.btn-clear{background:#39475c}.datebar{margin-top:10px;background:#062d6d;border:2px solid #208fe4;border-radius:10px;padding:10px 14px;display:grid;grid-template-columns:1fr 1fr;gap:12px;align-items:center;font-size:25px}.date-group{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.date-note{grid-column:1/-1;color:#d7f7ff;font-size:20px}.main{display:grid;grid-template-columns:60% 40%;min-height:640px;background:#edf6ff;color:#062047;border-radius:12px;margin-top:10px;overflow:hidden}.left{padding:18px 22px 10px 10px;border-right:6px solid #0b75c9}.right{padding:18px 10px 10px 22px}.head{text-align:center;color:#123d9a;font-size:42px;font-weight:800;line-height:1.05;margin-bottom:18px}.row{display:grid;grid-template-columns:1fr 380px;gap:18px;align-items:center;margin-bottom:16px}.th{font-size:34px;font-weight:700;line-height:1.05}.en{font-size:27px;font-weight:800;line-height:1.05}.green{color:#005b4a}.red{color:#8e102c}.val{display:flex;justify-content:flex-end;gap:6px;align-items:center}.date,.month,.year,.num,.monthbox input{font-family:inherit;border:3px solid #7894b4;background:#f7fbff;font-weight:800;color:#071b3d;text-align:center;padding:6px;border-radius:3px;box-shadow:inset 0 0 5px #0004}.date{width:92px;font-size:48px}.month{width:155px;font-size:30px}.year{width:135px;font-size:48px}.num{width:230px;font-size:58px}.num[readonly],.date[readonly],.month[readonly],.year[readonly]{background:#e7eef7}.rhead{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:12px;align-items:start}.monthbox{display:grid;gap:10px;width:260px}.monthbox input{width:100%;font-size:30px;background:#f8f4fb;color:#243a80}.cal{margin-top:16px;display:grid;grid-template-columns:repeat(7,1fr);gap:7px}.day{min-height:48px;border:2px solid #8aa7c7;background:#f2f6fb;color:#24354f;font-size:32px;font-weight:800;cursor:pointer;display:grid;place-items:center}.day.blank{opacity:.25;cursor:default}.day.future{background:#f2f6fb;color:#9aa7b6;cursor:default}.status-green{background:#006b58!important;color:white!important}.status-yellow{background:#d69a00!important;color:#111!important}.status-red{background:#9c1131!important;color:white!important}.auto-green{background:#006b58;color:white;box-shadow:inset 0 0 0 3px #70dbc8}.legend{margin-top:20px;font-size:22px;line-height:1.05}.legend-row{display:grid;grid-template-columns:34px 1fr;gap:12px;align-items:center;margin-bottom:12px}.box{width:32px;height:32px}.panel{margin-top:16px;padding:12px;background:#ffffffcc;border:2px dashed #0b75c9;border-radius:8px;display:grid;grid-template-columns:repeat(5,1fr);gap:10px}.sync{font-weight:800;color:#ffeb3b}.hint{font-size:20px;color:#d7f7ff}.footer{margin-top:12px;border-radius:14px;overflow:hidden;border:3px solid #208fe4;background:#ffffffd9;box-shadow:0 3px 10px #0005;color:#062047}.footer-main{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:12px;align-items:center;padding:12px 18px;background:linear-gradient(90deg,#020735,#063b97,#0077ff);color:white}.footer-brand{font-size:30px;font-weight:800;line-height:1}.footer-brand small{display:block;font-size:19px;font-weight:600;color:#d9fff5;margin-top:4px}.footer-maker{font-size:28px;font-weight:800;text-align:center}.footer-maker span{display:block;font-size:22px;font-weight:600;color:#eafff8}.footer-meta{text-align:right;font-size:21px;line-height:1.15}.footer-sub{display:grid;grid-template-columns:1fr auto;gap:10px;align-items:center;padding:8px 18px;color:#062047;font-size:20px;font-weight:700}.footer-sub .pill{background:#dcedff;border:1px solid #70aee8;padding:4px 10px;border-radius:999px;color:#064b92;font-size:18px}.export-sheet{position:absolute;left:-99999px;top:0;width:900px;background:#edf6ff;color:#062047;font-family:'TH Sarabun New','Sarabun',Tahoma,sans-serif;border:8px solid #062d6d;padding:18px}.ex-title{background:linear-gradient(90deg,#020735,#063b97,#0077ff);color:white;border-radius:12px;padding:18px;text-align:center;font-size:42px;font-weight:800}.ex-logo{max-width:260px;display:block;margin:0 auto 8px}.ex-titlebar{width:100%;height:86px;object-fit:cover;border-radius:8px;margin-bottom:10px}.ex-sub{font-size:26px;color:#d7f7ff}.ex-section{margin-top:18px;border:3px solid #0b75c9;border-radius:12px;background:white;overflow:hidden}.ex-section h2{margin:0;background:#062d6d;color:white;padding:10px 16px;font-size:34px}.ex-body{padding:14px 16px;font-size:28px}.ex-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.ex-card{border:2px solid #8aa7c7;border-radius:10px;padding:10px;background:#f5faff}.ex-label{font-size:24px;color:#36506f}.ex-value{font-size:42px;font-weight:800;color:#061a3b}.ex-calendar{display:grid;grid-template-columns:repeat(7,1fr);gap:6px}.ex-day{height:54px;border:2px solid #8aa7c7;display:grid;place-items:center;font-size:30px;font-weight:800;background:#f2f6fb}.ex-legend{display:grid;grid-template-columns:34px 1fr;gap:10px;align-items:center;margin:8px 0;font-size:24px}.ex-footer{margin-top:18px;text-align:center;font-size:24px;background:#04142e;color:white;border-radius:10px;padding:12px}@media(max-width:1100px){.brand-header,.top,.main,.row,.rhead,.toolbar,.footer-main,.footer-sub,.datebar{grid-template-columns:1fr}.brand-header{height:auto;text-align:center}.bcc-logo{margin:auto}.safety-circle{justify-self:center}.title-image{height:70px}.left{border-right:0;border-bottom:6px solid #0b75c9}.val{justify-content:flex-start;flex-wrap:wrap}.panel{grid-template-columns:1fr 1fr}.footer-meta,.footer-maker{text-align:left}.monthbox{width:100%}}\n</style></head><body>\n<div id=\"login\" class=\"login\"><div class=\"login-card\"><h1>BCC Safety Login</h1><p>เข้าสู่ระบบ Web Application</p><input id=\"loginUser\" placeholder=\"User\"><input id=\"loginPass\" type=\"password\" placeholder=\"Password\"><div id=\"loginError\" class=\"login-error\"></div><button onclick=\"doLogin()\">Login</button></div></div>\n<div id=\"app\" class=\"app hidden\">\n  <section class=\"unified-layout\">\n    <div class=\"brand-header\">\n      <div class=\"logo\"><img class=\"bcc-logo\" src=\"data:image/png;base64,\" alt=\"BCC Logo\"></div>\n      <div class=\"brand-title\">\n        <input id=\"companyName\" class=\"company-line\" value=\"บริษัท สายไฟฟ้าบางกอกเคเบิ้ล จำกัด\">\n        <input id=\"departmentTitle\" class=\"department-line\" readonly>\n      </div>\n      <div class=\"safety-circle\">SAFETY<br>FIRST<br>ปลอดภัยไว้ก่อน</div>\n    </div>\n    <div class=\"title-image\"><img class=\"title-image-img\" src=\"data:image/jpeg;base64,\" alt=\"Title Bar Image\"></div>\n  </section>\n<div class=\"toolbar\"><div>เวลา Real-time: <span id=\"clock\">-</span><br><span class=\"hint\">สถานะ Sync: <span id=\"sync\" class=\"sync\">กำลังเชื่อมต่อ</span></span></div><div>ดูข้อมูลแยกตามฝ่าย: <select id=\"departmentSelect\"></select> <input id=\"newDepartmentName\" placeholder=\"พิมพ์ชื่อฝ่ายใหม่\"></div><div><button class=\"btn-add\" onclick=\"addDepartment()\">+ เพิ่มฝ่าย</button> <button class=\"btn-del\" onclick=\"deleteDepartment()\">ลบฝ่าย</button> <button class=\"btn-clear\" onclick=\"logout()\">Logout</button></div></div>\n<div class=\"datebar\"><div class=\"date-group\">วันที่คำนวณ Safety Record: <select id=\"selectDay\"></select><select id=\"selectMonth\"></select><select id=\"selectYear\"></select></div><div class=\"date-group\">เดือนที่แสดง Accident Record: <select id=\"accMonth\"></select><select id=\"accYear\"></select></div><div class=\"date-note\">Auto Update สีเขียว = วันทำงานที่ไม่เกิดอุบัติเหตุ ตั้งแต่ 1/1/2566 ถึงวันที่ปัจจุบัน | วันอนาคต = ว่าง</div></div>\n<div class=\"main\"><div class=\"left\"><div class=\"head\">สถิติความปลอดภัย<br>SAFETY RECORD</div><div class=\"row\"><div><div class=\"th\">วันที่บันทึก</div><div class=\"en\">RECORD DATE</div></div><div class=\"val\"><input id=\"recordDay\" class=\"date\" readonly><input id=\"recordMonthTH\" class=\"month\" readonly><input id=\"recordYear\" class=\"year\" readonly></div></div><div class=\"row\"><div><div class=\"th green\">ทำงานมาแล้วโดยไม่เกิดอุบัติเหตุถึงขั้นหยุดงาน (วัน)</div><div class=\"en green\">OPERATED WITHOUT A LOST TIME ACCIDENT (DAYS)</div></div><div class=\"val\"><input id=\"operateDays\" class=\"num\" type=\"number\"></div></div><div class=\"row\"><div><div class=\"th green\">เป้าหมาย (วัน)</div><div class=\"en green\">TARGET (DAYS)</div></div><div class=\"val\"><input id=\"targetDays\" class=\"num\" type=\"number\"></div></div><div class=\"row\"><div><div class=\"th red\">เกิดอุบัติเหตุถึงขั้นหยุดงานครั้งสุดท้ายเมื่อ</div><div class=\"en red\">LAST ACCIDENT OCCURRED</div></div><div class=\"val\"><input id=\"lastAccidentDay\" class=\"date\" readonly><input id=\"lastAccidentMonthTH\" class=\"month\" readonly><input id=\"lastAccidentYear\" class=\"year\" readonly></div></div><div class=\"row\"><div><div class=\"th green\">สถิติที่ดีที่สุดที่ไม่เกิดอุบัติเหตุถึงขั้นหยุดงาน (วัน)</div><div class=\"en green\">THE BEST RECORD (DAYS)</div></div><div class=\"val\"><input id=\"bestRecord\" class=\"num\" type=\"number\"></div></div><div class=\"panel\"><button class=\"btn-save\" onclick=\"saveNow()\">บันทึกทันที</button><button class=\"btn-export\" onclick=\"exportJSON()\">Export JSON</button><button class=\"btn-export\" onclick=\"exportImage()\">Export รูปแนวตั้ง</button><button class=\"btn-clear\" onclick=\"clearDays()\">ล้างสีเดือนนี้</button><button class=\"btn-del\" onclick=\"resetDepartment()\">Reset ฝ่ายนี้</button></div></div><div class=\"right\"><div class=\"rhead\"><div class=\"head\" style=\"text-align:left;margin-bottom:8px\">สถิติความปลอดภัยประจำเดือน<br>ACCIDENT RECORD FOR</div><div class=\"monthbox\"><input id=\"displayMonthTH\" readonly><input id=\"displayMonthEN\" readonly></div></div><div id=\"cal\" class=\"cal\"></div><div class=\"legend\"><div class=\"legend-row\"><div class=\"box status-green\"></div><div>วันทำงานที่ไม่เกิดอุบัติเหตุ<br>REGULAR WORKING DAY WITH NO LOST TIME ACCIDENT</div></div><div class=\"legend-row\"><div class=\"box status-yellow\"></div><div>วันที่เกิดอุบัติเหตุแต่ไม่ถึงขั้นหยุดงาน<br>ACCIDENT OCCURRED WITH NO LOST TIME</div></div><div class=\"legend-row\"><div class=\"box status-red\"></div><div>วันที่เกิดอุบัติเหตุถึงขั้นหยุดงาน<br>LOST TIME ACCIDENT</div></div></div></div></div><footer class=\"footer\"><div class=\"footer-main\"><div class=\"footer-brand\">BCC Safety Web Application<small>Interactive Safety Record Dashboard</small></div><div class=\"footer-maker\">ผู้จัดทำ: Siriphan<span>IT Officer / Web Application Developer</span></div><div class=\"footer-meta\">Version 11.0<br>Manual Number Edit<br>Cloudflare Workers + Real-time Sync</div></div><div class=\"footer-sub\"><div>ใช้สำหรับติดตามสถิติความปลอดภัย แยกข้อมูลตามฝ่าย เลือกเดือนที่แสดง และ Export PNG / JSON</div><div class=\"pill\">© 2026 Bangkok Cable</div></div></footer></div>\n<script src=\"https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/dist/html2canvas.min.js\"></script><script>\nconst USER='BCC',PASS='Siriphan.m';const monthsTH=['มกราคม','กุมภาพันธ์','มีนาคม','เมษายน','พฤษภาคม','มิถุนายน','กรกฎาคม','สิงหาคม','กันยายน','ตุลาคม','พฤศจิกายน','ธันวาคม'];const monthsEN=['JANUARY','FEBRUARY','MARCH','APRIL','MAY','JUNE','JULY','AUGUST','SEPTEMBER','OCTOBER','NOVEMBER','DECEMBER'];let appData={appVersion:'11.0.0',companyName:'บริษัท สายไฟฟ้าบางกอกเคเบิ้ล จำกัด',currentDepartmentId:'bcc2-insulation-packing',departments:[{id:'bcc2-insulation-packing',name:'ฝ่ายหุ้มฉนวนและบรรจุสาย BCC2',targetDays:'2937',monthRecords:{},data:{}}]};let ws,timer;function doLogin(){if(loginUser.value===USER&&loginPass.value===PASS){sessionStorage.setItem('bcc_login','1');login.classList.add('hidden');app.classList.remove('hidden');connect()}else loginError.textContent='User หรือ Password ไม่ถูกต้อง'}function logout(){sessionStorage.removeItem('bcc_login');location.reload()}function initAuth(){if(sessionStorage.getItem('bcc_login')==='1'){login.classList.add('hidden');app.classList.remove('hidden');connect()}}function uid(){return 'dep-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7)}function todayTH(){const n=new Date();return {d:n.getDate(),m:n.getMonth()+1,y:n.getFullYear()+543}}function currentDep(){return appData.departments.find(d=>d.id===appData.currentDepartmentId)||appData.departments[0]}function key(y,m){return y+'-'+String(m).padStart(2,'0')}function ceY(be){return Number(be)-543}function daysInMonth(be,m){return new Date(ceY(be),m,0).getDate()}function dateObj(be,m,d){return new Date(ceY(be),m-1,d)}function dateDiff(a,b){return Math.floor((b-a)/86400000)}function startAuto(){return dateObj(2566,1,1)}function todayDate(){const t=todayTH();return dateObj(t.y,t.m,t.d)}function isFuture(y,m,d){return dateObj(Number(y),Number(m),Number(d))>todayDate()}function isAutoGreen(y,m,d){const dt=dateObj(y,m,d);return dt>=startAuto()&&dt<=todayDate()}function normalize(){if(!Array.isArray(appData.departments)||!appData.departments.length)appData.departments=[{id:uid(),name:'ฝ่ายเริ่มต้น',targetDays:'2937',monthRecords:{},data:{}}];if(!appData.currentDepartmentId)appData.currentDepartmentId=appData.departments[0].id;appData.departments.forEach(d=>{d.targetDays=d.targetDays||d.data?.targetDays||'2937';d.monthRecords=d.monthRecords||{};d.manualOverrides=d.manualOverrides||{};if(!d.data)d.data={}})}function setStatus(x){sync.textContent=x}function fillYearSelect(sel){sel.innerHTML='';for(let y=2566;y<=2575;y++){let o=document.createElement('option');o.value=y;o.textContent=y;sel.appendChild(o)}}function fillMonthSelect(sel){sel.innerHTML='';monthsTH.forEach((m,i)=>{let o=document.createElement('option');o.value=i+1;o.textContent=m;sel.appendChild(o)})}function initDateSelectors(){fillYearSelect(selectYear);fillMonthSelect(selectMonth);fillYearSelect(accYear);fillMonthSelect(accMonth);const t=todayTH();selectYear.value=t.y;selectMonth.value=t.m;accYear.value=t.y;accMonth.value=t.m;fillDays(t.d)}function fillDays(prefer){const max=daysInMonth(selectYear.value,selectMonth.value);selectDay.innerHTML='';for(let d=1;d<=max;d++){let o=document.createElement('option');o.value=d;o.textContent=d;selectDay.appendChild(o)}selectDay.value=Math.min(prefer||1,max)}function renderDepartments(){normalize();departmentSelect.innerHTML='';appData.departments.forEach(d=>{const o=document.createElement('option');o.value=d.id;o.textContent=d.name;departmentSelect.appendChild(o)});departmentSelect.value=appData.currentDepartmentId;departmentTitle.value=currentDep().name}function monthRecord(dep,y=accYear.value,m=accMonth.value){const k=key(y,m);dep.monthRecords[k]=dep.monthRecords[k]||{};return dep.monthRecords[k]}function effectiveStatus(dep,y,m,d){if(isFuture(y,m,d))return '';const rec=dep.monthRecords[key(y,m)]||{};return rec[d]||(isAutoGreen(Number(y),Number(m),Number(d))?'green':'')}function computeStats(dep){const y=Number(selectYear.value),m=Number(selectMonth.value),d=Number(selectDay.value),selected=dateObj(y,m,d);let lastRed=null,best=0,currentStreak=0;for(let yy=2566;yy<=y;yy++){for(let mm=1;mm<=12;mm++){if(yy===y&&mm>m)break;const max=daysInMonth(yy,mm);for(let dd=1;dd<=max;dd++){const dt=dateObj(yy,mm,dd);if(dt>selected||dt>todayDate())break;const status=effectiveStatus(dep,yy,mm,dd);if(status==='red'){if(currentStreak>best)best=currentStreak;currentStreak=0;lastRed={y:yy,m:mm,d:dd,date:dt}}else if(dt>=startAuto()){currentStreak++}}}}if(currentStreak>best)best=currentStreak;const end=selected>todayDate()?todayDate():selected;const operate=lastRed?Math.max(0,dateDiff(lastRed.date,end)):dateDiff(startAuto(),end)+1;return {operate:Math.max(0,operate),best,lastRed}}function apply(){normalize();companyName.value=appData.companyName||'';renderDepartments();const dep=currentDep();targetDays.value=dep.targetDays||'2937';recordDay.value=selectDay.value;recordMonthTH.value=monthsTH[selectMonth.value-1];recordYear.value=selectYear.value;displayMonthTH.value=monthsTH[accMonth.value-1];displayMonthEN.value=monthsEN[accMonth.value-1];const s=computeStats(dep);dep.manualOverrides=dep.manualOverrides||{};operateDays.value=(dep.manualOverrides.operateDays!==undefined?dep.manualOverrides.operateDays:s.operate);bestRecord.value=(dep.manualOverrides.bestRecord!==undefined?dep.manualOverrides.bestRecord:s.best);if(s.lastRed){lastAccidentDay.value=s.lastRed.d;lastAccidentMonthTH.value=monthsTH[s.lastRed.m-1];lastAccidentYear.value=s.lastRed.y}else{lastAccidentDay.value='-';lastAccidentMonthTH.value='-';lastAccidentYear.value='-'}drawCalendar()}function collect(){appData.companyName=companyName.value;const dep=currentDep();dep.targetDays=targetDays.value;dep.manualOverrides=dep.manualOverrides||{};if(dep.manualOverrides.operateDays!==undefined)dep.manualOverrides.operateDays=operateDays.value;if(dep.manualOverrides.bestRecord!==undefined)dep.manualOverrides.bestRecord=bestRecord.value}function setManualNumber(field,key){const dep=currentDep();dep.manualOverrides=dep.manualOverrides||{};dep.manualOverrides[key]=document.getElementById(field).value;send()}function clearManualNumber(key){const dep=currentDep();dep.manualOverrides=dep.manualOverrides||{};delete dep.manualOverrides[key];apply();send()}function drawCalendar(){const dep=currentDep(),rec=monthRecord(dep),max=daysInMonth(accYear.value,accMonth.value);cal.innerHTML='';for(let i=1;i<=31;i++){const d=document.createElement('div');if(i>max){d.className='day blank';d.textContent='';cal.appendChild(d);continue}const future=isFuture(accYear.value,accMonth.value,i);if(future){d.className='day future';d.textContent=i;d.title='วันอนาคต = ว่าง';d.onclick=()=>clearFutureDay(i);cal.appendChild(d);continue}const stored=rec[i]||'';const eff=stored||(isAutoGreen(Number(accYear.value),Number(accMonth.value),i)?'green':'');d.className='day'+(stored?' status-'+stored:(eff==='green'?' auto-green':''));d.textContent=i;d.onclick=()=>toggleDay(i);cal.appendChild(d)}}function clearFutureDay(i){const rec=monthRecord(currentDep());delete rec[i];apply();send()}function send(){collect();if(ws&&ws.readyState===1){ws.send(JSON.stringify({type:'update',data:appData}));setStatus('บันทึกและ Sync แล้ว')}else fetch('/api/data',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(appData)}).then(()=>setStatus('บันทึกผ่าน API แล้ว'))}function autoSave(){clearTimeout(timer);timer=setTimeout(()=>{send();apply()},180)}function saveNow(){send();apply()}function toggleDay(i){if(isFuture(accYear.value,accMonth.value,i)){clearFutureDay(i);return}const rec=monthRecord(currentDep()),cur=rec[i]||'',auto=isAutoGreen(Number(accYear.value),Number(accMonth.value),i);if(!cur)rec[i]=auto?'yellow':'green';else if(cur==='green')rec[i]='yellow';else if(cur==='yellow')rec[i]='red';else delete rec[i];apply();send()}function clearDays(){currentDep().monthRecords[key(accYear.value,accMonth.value)]={};apply();send()}function resetDepartment(){if(!confirm('Reset ข้อมูลของฝ่ายนี้ทั้งหมดหรือไม่?'))return;const dep=currentDep();dep.targetDays='2937';dep.monthRecords={};dep.manualOverrides={};apply();send()}function addDepartment(){const name=newDepartmentName.value.trim();if(!name){alert('กรุณาพิมพ์ชื่อฝ่าย');return}const d={id:uid(),name,targetDays:'2937',monthRecords:{},manualOverrides:{},data:{}};appData.departments.push(d);appData.currentDepartmentId=d.id;newDepartmentName.value='';apply();send()}function deleteDepartment(){if(appData.departments.length<=1){alert('ต้องมีอย่างน้อย 1 ฝ่าย');return}const dep=currentDep();if(!confirm('ต้องการลบ '+dep.name+' หรือไม่?'))return;appData.departments=appData.departments.filter(d=>d.id!==dep.id);appData.currentDepartmentId=appData.departments[0].id;apply();send()}function exportJSON(){collect();const b=new Blob([JSON.stringify(appData,null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='bcc-safety-webapp-v11.json';a.click();URL.revokeObjectURL(u)}function exportCalendarHtml(){const dep=currentDep(),max=daysInMonth(accYear.value,accMonth.value);let out='';for(let i=1;i<=31;i++){if(i>max){out+='<div class=\"ex-day\"></div>';continue}const s=effectiveStatus(dep,accYear.value,accMonth.value,i);out+='<div class=\"ex-day '+(s?'status-'+s:'')+'\">'+i+'</div>'}return out}function buildPortrait(){const dep=currentDep(),s=computeStats(dep),dateText=selectDay.value+' '+monthsTH[selectMonth.value-1]+' '+selectYear.value,last=s.lastRed?s.lastRed.d+' '+monthsTH[s.lastRed.m-1]+' '+s.lastRed.y:'-';const div=document.createElement('div');div.className='export-sheet';div.innerHTML='<div class=\"ex-title\"><img class=\"ex-logo\" src=\"data:image/png;base64,\" alt=\"BCC Logo\"><img class=\"ex-titlebar\" src=\"data:image/jpeg;base64,\" alt=\"Title Bar Image\">BCC Safety Record Web Application<div class=\"ex-sub\">ข้อมูลฝ่าย > สถิติความปลอดภัย > สถิติความปลอดภัยประจำเดือน</div></div><section class=\"ex-section\"><h2>1) ข้อมูลฝ่าย</h2><div class=\"ex-body\"><div class=\"ex-grid\"><div class=\"ex-card\"><div class=\"ex-label\">บริษัท</div><div class=\"ex-value\" style=\"font-size:30px\">'+companyName.value+'</div></div><div class=\"ex-card\"><div class=\"ex-label\">ฝ่าย</div><div class=\"ex-value\" style=\"font-size:30px\">'+dep.name+'</div></div><div class=\"ex-card\"><div class=\"ex-label\">วันที่คำนวณ</div><div class=\"ex-value\" style=\"font-size:34px\">'+dateText+'</div></div><div class=\"ex-card\"><div class=\"ex-label\">เดือนที่แสดง</div><div class=\"ex-value\" style=\"font-size:34px\">'+monthsTH[accMonth.value-1]+' / '+monthsEN[accMonth.value-1]+' '+accYear.value+'</div></div></div></div></section><section class=\"ex-section\"><h2>2) สถิติความปลอดภัย</h2><div class=\"ex-body\"><div class=\"ex-grid\"><div class=\"ex-card\"><div class=\"ex-label\">OPERATED WITHOUT LOST TIME ACCIDENT</div><div class=\"ex-value\">'+s.operate+' วัน</div></div><div class=\"ex-card\"><div class=\"ex-label\">TARGET</div><div class=\"ex-value\">'+targetDays.value+' วัน</div></div><div class=\"ex-card\"><div class=\"ex-label\">LAST ACCIDENT OCCURRED</div><div class=\"ex-value\" style=\"font-size:34px\">'+last+'</div></div><div class=\"ex-card\"><div class=\"ex-label\">THE BEST RECORD</div><div class=\"ex-value\">'+s.best+' วัน</div></div></div></div></section><section class=\"ex-section\"><h2>3) สถิติความปลอดภัยประจำเดือน</h2><div class=\"ex-body\"><div style=\"font-size:30px;font-weight:800;margin-bottom:8px\">ACCIDENT RECORD FOR '+monthsTH[accMonth.value-1]+' / '+monthsEN[accMonth.value-1]+' '+accYear.value+'</div><div class=\"ex-calendar\">'+exportCalendarHtml()+'</div><div style=\"margin-top:14px\"><div class=\"ex-legend\"><div class=\"box status-green\"></div><div>วันทำงานที่ไม่เกิดอุบัติเหตุ / REGULAR WORKING DAY WITH NO LOST TIME ACCIDENT</div></div><div class=\"ex-legend\"><div class=\"box status-yellow\"></div><div>วันที่เกิดอุบัติเหตุแต่ไม่ถึงขั้นหยุดงาน / ACCIDENT OCCURRED WITH NO LOST TIME</div></div><div class=\"ex-legend\"><div class=\"box status-red\"></div><div>วันที่เกิดอุบัติเหตุถึงขั้นหยุดงาน / LOST TIME ACCIDENT</div></div></div></div></section><div class=\"ex-footer\">ผู้จัดทำ: Siriphan | BCC Safety Web Application v11 | Unified Layout</div>';return div}async function exportImage(){collect();setStatus('กำลัง Export รูปแนวตั้ง PNG');const dep=currentDep();const safe=(dep.name||'department').replace(/[\\\\/:*?\"<>|\\s]+/g,'-').slice(0,60);const sheet=buildPortrait();document.body.appendChild(sheet);try{const canvas=await html2canvas(sheet,{backgroundColor:'#edf6ff',scale:2,useCORS:true,logging:false});const a=document.createElement('a');a.href=canvas.toDataURL('image/png');a.download='bcc-safety-portrait-'+safe+'-'+accYear.value+'-'+accMonth.value+'.png';a.click();setStatus('Export รูปแนวตั้งสำเร็จ')}catch(e){alert('Export รูปไม่สำเร็จ: '+e.message);setStatus('Export รูปไม่สำเร็จ')}finally{sheet.remove()}}function clock(){document.getElementById('clock').textContent=new Date().toLocaleString('th-TH',{dateStyle:'full',timeStyle:'medium'})}function connect(){if(ws&&ws.readyState<=1)return;const p=location.protocol==='https:'?'wss':'ws';ws=new WebSocket(p+'://'+location.host+'/ws');ws.onopen=()=>setStatus('เชื่อมต่อ Real-time แล้ว');ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.type==='init'||m.type==='update'){appData=m.data;normalize();apply();setStatus(m.type==='init'?'โหลดข้อมูลสำเร็จ':'รับข้อมูล Real-time แล้ว')}};ws.onclose=()=>{setStatus('หลุดการเชื่อมต่อ กำลังลองใหม่');setTimeout(connect,2000)};ws.onerror=()=>setStatus('WebSocket error')}function bind(){companyName.addEventListener('input',autoSave);targetDays.addEventListener('input',autoSave);operateDays.addEventListener('input',()=>setManualNumber('operateDays','operateDays'));bestRecord.addEventListener('input',()=>setManualNumber('bestRecord','bestRecord'));departmentSelect.addEventListener('change',e=>{collect();appData.currentDepartmentId=e.target.value;apply();send()});selectYear.addEventListener('change',()=>{fillDays(selectDay.value);apply();send()});selectMonth.addEventListener('change',()=>{fillDays(selectDay.value);apply();send()});selectDay.addEventListener('change',()=>{apply();send()});accYear.addEventListener('change',()=>{apply();send()});accMonth.addEventListener('change',()=>{apply();send()})}initDateSelectors();bind();apply();clock();setInterval(clock,1000);initAuth();\n</script></body></html>";
export default { async fetch(request, env) { const url=new URL(request.url); const id=env.SAFETY_DASHBOARD.idFromName("main-dashboard"); const obj=env.SAFETY_DASHBOARD.get(id); if(url.pathname==="/ws"||url.pathname==="/api/data")return obj.fetch(request); if(url.pathname==="/"||url.pathname==="/index.html")return new Response(html,{headers:{"content-type":"text/html; charset=UTF-8","cache-control":"no-store"}}); return new Response("Not found",{status:404}); } };
